  ('hi', 'whatsNew.item.workMode.title', $json$"हर चैट में योजना या डेवलपमेंट चुनें"$json$::jsonb),
  ('hi', 'whatsNew.item.workMode.detail', $json$"अब हर चैट में संदेश बॉक्स के नीचे कार्य मोड चुनने का विकल्प है: ऑटो (पहले की तरह Jev हर अनुरोध के लिए चुनता है), योजना या डेवलपमेंट। आप /plan, /build या /auto भी टाइप कर सकते हैं, Ctrl+. (Mac पर ⌘.) दबा सकते हैं या कमांड पैलेट का उपयोग कर सकते हैं। अगर चैट योजना मोड में है और आप लागू करने को कहते हैं, या ऑटो में योजना के बाद फिर से लागू करने को कहते हैं, तो Jev खुद डेवलपमेंट पर चला जाता है और जवाब में बताता है, साथ में पूर्ववत करने का बटन होता है।"$json$::jsonb),
